from decimal import Decimal

MODEL_PRICING = {
    "model-small": {
        "input": Decimal("0.20"),
        "output": Decimal("0.80")
    },
    "model-large": {
        "input": Decimal("2.00"),
        "output": Decimal("8.00")
    }
}

def estimate_cost(
    model,
    input_tokens,
    output_tokens
):
    prices = MODEL_PRICING[model]

    input_cost = (
        Decimal(input_tokens)
        * prices["input"]
        / Decimal("1000000")
    )

    output_cost = (
        Decimal(output_tokens)
        * prices["output"]
        / Decimal("1000000")
    )

    return input_cost + output_cost

def enforce_budget(
    estimated_cost,
    remaining_budget
):
    if estimated_cost > remaining_budget:
        raise ValueError("Budget exceeded")

    return True

import hashlib
from pathlib import Path

def calculate_sha256(file_path: str):
    digest = hashlib.sha256()

    with open(file_path, "rb") as file:
        for chunk in iter(
            lambda: file.read(1024 * 1024),
            b""
        ):
            digest.update(chunk)

    return digest.hexdigest()

def verify_model(
    file_path: str,
    trusted_checksum: str
):
    actual_checksum = calculate_sha256(file_path)

    if actual_checksum != trusted_checksum:
        raise ValueError(
            "Model integrity verification failed"
        )

    return True
